// StrictServerInterface represents all server handlers.
type StrictServerInterface interface {
	// ListCandidates List or search candidates, newest first
	// (GET /v1/candidates)
	ListCandidates(ctx context.Context, request ListCandidatesRequestObject) (ListCandidatesResponseObject, error)
	// CreateCandidate Add a candidate
	// (POST /v1/candidates)
	CreateCandidate(ctx context.Context, request CreateCandidateRequestObject) (CreateCandidateResponseObject, error)
	// GetCandidate Get a candidate
	// (GET /v1/candidates/{candidateId})
	GetCandidate(ctx context.Context, request GetCandidateRequestObject) (GetCandidateResponseObject, error)
	// UpdateCandidate Change some fields of a candidate
	// (PATCH /v1/candidates/{candidateId})
	UpdateCandidate(ctx context.Context, request UpdateCandidateRequestObject) (UpdateCandidateResponseObject, error)
	// PutCandidateCompensation Set a candidate's current and expected salary
	// (PUT /v1/candidates/{candidateId}/compensation)
	PutCandidateCompensation(ctx context.Context, request PutCandidateCompensationRequestObject) (PutCandidateCompensationResponseObject, error)
	// ListCandidateDocuments List a candidate's documents, newest first
	// (GET /v1/candidates/{candidateId}/documents)
	ListCandidateDocuments(ctx context.Context, request ListCandidateDocumentsRequestObject) (ListCandidateDocumentsResponseObject, error)
	// UploadCandidateDocument Upload a CV or other document (PDF or DOCX, up to 10 MB)
	// (POST /v1/candidates/{candidateId}/documents)
	UploadCandidateDocument(ctx context.Context, request UploadCandidateDocumentRequestObject) (UploadCandidateDocumentResponseObject, error)
	// GetDocument Get a document, including its extracted text
	// (GET /v1/documents/{documentId})
	GetDocument(ctx context.Context, request GetDocumentRequestObject) (GetDocumentResponseObject, error)
	// GetMe Who is signed in, their tenant, and what they may do
	// (GET /v1/me)
	GetMe(ctx context.Context, request GetMeRequestObject) (GetMeResponseObject, error)
}

type StrictHandlerFunc func(ctx context.Context, w http.ResponseWriter, r *http.Request, request any) (any, error)
type StrictMiddlewareFunc func(f StrictHandlerFunc, operationID string) StrictHandlerFunc

type StrictHTTPServerOptions struct {
	RequestErrorHandlerFunc  func(w http.ResponseWriter, r *http.Request, err error)
	ResponseErrorHandlerFunc func(w http.ResponseWriter, r *http.Request, err error)
}

func NewStrictHandler(ssi StrictServerInterface, middlewares []StrictMiddlewareFunc) ServerInterface {
	return &strictHandler{ssi: ssi, middlewares: middlewares, options: StrictHTTPServerOptions{
		RequestErrorHandlerFunc: func(w http.ResponseWriter, r *http.Request, err error) {
			http.Error(w, err.Error(), http.StatusBadRequest)
		},
		ResponseErrorHandlerFunc: func(w http.ResponseWriter, r *http.Request, err error) {
			http.Error(w, err.Error(), http.StatusInternalServerError)
		},
	}}
}

func NewStrictHandlerWithOptions(ssi StrictServerInterface, middlewares []StrictMiddlewareFunc, options StrictHTTPServerOptions) ServerInterface {
	if options.RequestErrorHandlerFunc == nil {
		options.RequestErrorHandlerFunc = func(w http.ResponseWriter, r *http.Request, err error) {
			http.Error(w, err.Error(), http.StatusBadRequest)
		}
	}
	if options.ResponseErrorHandlerFunc == nil {
		options.ResponseErrorHandlerFunc = func(w http.ResponseWriter, r *http.Request, err error) {
			http.Error(w, err.Error(), http.StatusInternalServerError)
		}
	}
	return &strictHandler{ssi: ssi, middlewares: middlewares, options: options}
}

